def __repr__(self):
    parts = ['Check(']
    if self.spec is not T:
        parts.append(repr(self.spec))
    if self.types:
        parts.append('type=%r' % self.types)
    if self.instance_of:
        parts.append('instance_of=%r' % self.instance_of)
    if self.vals:
        parts.append('vals=%r' % self.vals)
    if self.validators:
        parts.append('validators=%r' % [v.__name__ if callable(v) else v for v in self.validators])
    parts.append(')')
    return ''.join(parts)

